// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, uint256 ts, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        uint256 bn = bound(blockNumber, 1, 1000000);
        // strictly increasing timestamp relative to stored pastBlockTime (starts at 0)
        vm.warp(1000 + (ts % 1000000));
        vm.roll(bn);

        vm.deal(actor, 10 ether);
        uint256 before = address(c).balance;
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // Rule: payout (balance drained to 0) happens exactly when block.number % 15 == 0.
        bool paidOut = address(c).balance == 0;
        assertTrue(paidOut == (bn % 15 == 0), "payout iff block.number % 15 == 0");
        if (!paidOut) {
            assertTrue(address(c).balance == before + 10 ether);
        }
    }
}
